PRODUCTION_SOURCE = '"""\nOLA-039\nOracle Persisted Cohort Lineage Bridge\n\nCanonical adapter boundary connecting:\n- OLA-038 persisted-cycle canonical cohort bundle\nto:\n- OLA-037 post-persistence lineage cycle coordinator\n\nPurpose:\n- consume one immutable OLA-038 bundle\n- derive OLA-037 persistence evidence without reinterpreting cycle semantics\n- pass the exact OLA-038 CanonicalObservation cohort into OLA-037\n- preserve acquisition batch identity, canonical count, persistence count,\n  cycle completion time, and upstream OLA-017 identity\n- return one immutable deterministic bridge receipt\n\nThis boundary performs no acquisition, persistence, intelligence interpretation,\nsignal scoring, alerting, Q Series handoff, authorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nimport json\nfrom typing import Any\n\nfrom .oracle_persisted_cycle_canonical_cohort_bundle_contract import (\n    OraclePersistedCycleCanonicalCohortBundle,\n    PersistedCycleCanonicalCohortBundleInvariantError,\n)\nfrom .oracle_post_persistence_lineage_cycle_coordinator import (\n    OraclePostPersistenceLineageCycleCoordinator,\n    PersistedAcquisitionCycleEvidence,\n    PostPersistenceLineageCycleContractError,\n    PostPersistenceLineageCycleInvariantError,\n    PostPersistenceLineageCycleReceipt,\n)\n\n\nSCHEMA_VERSION = "OLA-039"\nENGINE_ID = "OLA-039"\nRECEIPT_TYPE = "oracle_persisted_cohort_lineage_bridge_receipt"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass PersistedCohortLineageBridgeContractError(ValueError):\n    """Raised when OLA-039 bridge input is malformed."""\n\n\nclass PersistedCohortLineageBridgeInvariantError(RuntimeError):\n    """Raised when permanent OLA-039 invariants are violated."""\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PersistedCohortLineageBridgeReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    bundle_hash: str\n    upstream_schema_version: str\n    upstream_engine_id: str\n    acquisition_batch_id: str\n    canonical_count: int\n    persistence_count: int\n    cycle_completed_at: str\n    coordination_hash: str\n    transition_count: int\n    lineage_market_count_after: int\n    lineage_record_count_after: int\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    bridge_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.receipt_type != RECEIPT_TYPE:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "receipt type invariant violated"\n            )\n\n        if self.upstream_schema_version != "OLA-017":\n            raise PersistedCohortLineageBridgeInvariantError(\n                "upstream schema identity invariant violated"\n            )\n\n        if self.upstream_engine_id != "OLA-017":\n            raise PersistedCohortLineageBridgeInvariantError(\n                "upstream engine identity invariant violated"\n            )\n\n        if self.canonical_count <= 0:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "canonical count must be positive"\n            )\n\n        if self.persistence_count != self.canonical_count:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "persistence equality invariant violated"\n            )\n\n        if self.lineage_record_count_after < self.canonical_count:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "lineage record count cannot trail canonical count"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise PersistedCohortLineageBridgeInvariantError(\n                "OLA-039 read-only authority invariants violated"\n            )\n\n\nclass OraclePersistedCohortLineageBridge:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        coordinator: (\n            OraclePostPersistenceLineageCycleCoordinator | None\n        ) = None,\n    ) -> None:\n        self._coordinator = (\n            coordinator\n            if coordinator is not None\n            else OraclePostPersistenceLineageCycleCoordinator()\n        )\n\n        if not isinstance(\n            self._coordinator,\n            OraclePostPersistenceLineageCycleCoordinator,\n        ):\n            raise PersistedCohortLineageBridgeContractError(\n                "coordinator must be an OLA-037 "\n                "OraclePostPersistenceLineageCycleCoordinator"\n            )\n\n    @property\n    def coordinator(\n        self,\n    ) -> OraclePostPersistenceLineageCycleCoordinator:\n        return self._coordinator\n\n    def advance(\n        self,\n        *,\n        bundle: OraclePersistedCycleCanonicalCohortBundle,\n    ) -> PersistedCohortLineageBridgeReceipt:\n        if not isinstance(\n            bundle,\n            OraclePersistedCycleCanonicalCohortBundle,\n        ):\n            raise PersistedCohortLineageBridgeContractError(\n                "bundle must be an OLA-038 "\n                "OraclePersistedCycleCanonicalCohortBundle"\n            )\n\n        try:\n            bundle.assert_invariants()\n        except PersistedCycleCanonicalCohortBundleInvariantError as exc:\n            raise PersistedCohortLineageBridgeInvariantError(\n                f"OLA-038 bundle invariant failed: {exc}"\n            ) from exc\n\n        evidence = PersistedAcquisitionCycleEvidence.create(\n            schema_version=bundle.upstream_schema_version,\n            engine_id=bundle.upstream_engine_id,\n            cycle_status=bundle.cycle_status,\n            acquisition_batch_id=bundle.acquisition_batch_id,\n            canonical_count=bundle.canonical_count,\n            persistence_count=bundle.persistence_count,\n            cycle_completed_at=bundle.cycle_completed_at,\n            read_only=bundle.read_only,\n            execution_allowed=bundle.execution_allowed,\n        )\n\n        try:\n            coordination = self._coordinator.coordinate(\n                cycle_evidence=evidence,\n                canonical_observations=bundle.canonical_observations,\n            )\n        except PostPersistenceLineageCycleContractError as exc:\n            raise PersistedCohortLineageBridgeContractError(\n                f"OLA-037 coordinator rejected bundle: {exc}"\n            ) from exc\n        except PostPersistenceLineageCycleInvariantError as exc:\n            raise PersistedCohortLineageBridgeInvariantError(\n                f"OLA-037 coordinator invariant failed: {exc}"\n            ) from exc\n\n        self._assert_binding(\n            bundle=bundle,\n            coordination=coordination,\n        )\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": RECEIPT_TYPE,\n            "bundle_hash": bundle.bundle_hash,\n            "upstream_schema_version": bundle.upstream_schema_version,\n            "upstream_engine_id": bundle.upstream_engine_id,\n            "acquisition_batch_id": bundle.acquisition_batch_id,\n            "canonical_count": bundle.canonical_count,\n            "persistence_count": bundle.persistence_count,\n            "cycle_completed_at": bundle.cycle_completed_at.isoformat(),\n            "coordination_hash": coordination.coordination_hash,\n            "transition_count": coordination.transition_count,\n            "lineage_market_count_after": (\n                coordination.lineage_market_count_after\n            ),\n            "lineage_record_count_after": (\n                coordination.lineage_record_count_after\n            ),\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = PersistedCohortLineageBridgeReceipt(\n            **payload,\n            bridge_hash=_stable_hash(payload),\n        )\n\n        receipt.assert_invariants()\n        return receipt\n\n    @staticmethod\n    def _assert_binding(\n        *,\n        bundle: OraclePersistedCycleCanonicalCohortBundle,\n        coordination: PostPersistenceLineageCycleReceipt,\n    ) -> None:\n        if (\n            coordination.upstream_schema_version\n            != bundle.upstream_schema_version\n        ):\n            raise PersistedCohortLineageBridgeInvariantError(\n                "upstream schema binding invariant violated"\n            )\n\n        if (\n            coordination.upstream_engine_id\n            != bundle.upstream_engine_id\n        ):\n            raise PersistedCohortLineageBridgeInvariantError(\n                "upstream engine binding invariant violated"\n            )\n\n        if (\n            coordination.acquisition_batch_id\n            != bundle.acquisition_batch_id\n        ):\n            raise PersistedCohortLineageBridgeInvariantError(\n                "acquisition batch binding invariant violated"\n            )\n\n        if coordination.canonical_count != bundle.canonical_count:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "canonical count binding invariant violated"\n            )\n\n        if coordination.persistence_count != bundle.persistence_count:\n            raise PersistedCohortLineageBridgeInvariantError(\n                "persistence count binding invariant violated"\n            )\n\n        if (\n            coordination.cycle_completed_at\n            != bundle.cycle_completed_at.isoformat()\n        ):\n            raise PersistedCohortLineageBridgeInvariantError(\n                "cycle completion clock binding invariant violated"\n            )\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_persisted_cohort_lineage_bridge import (\n    OraclePersistedCohortLineageBridge,\n    PersistedCohortLineageBridgeContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_persisted_cycle_canonical_cohort_bundle_contract import (\n    OraclePersistedCycleCanonicalCohortBundle,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 12, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 12, 0, 15, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 14, 12, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_bundle(\n    *,\n    cycle_number,\n    completed_at,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.039.{cycle_number}"\n\n    observations = tuple(\n        build_observation(\n            market_id=f"KXTEST-BRIDGE-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9100"\n                if changed_market == f"KXTEST-BRIDGE-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n    cycle_result = {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "cycle_status": "completed",\n        "canonical_count": 5,\n        "postgresql_routing_record_delta": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n    return OraclePersistedCycleCanonicalCohortBundle.create(\n        ola_017_cycle_result=cycle_result,\n        canonical_observations=observations,\n        cycle_completed_at=completed_at,\n    )\n\n\ndef run_first_bundle_test():\n    bridge = OraclePersistedCohortLineageBridge()\n\n    bundle = build_bundle(\n        cycle_number=1,\n        completed_at=T1,\n    )\n\n    receipt = bridge.advance(bundle=bundle)\n\n    assert receipt.bundle_hash == bundle.bundle_hash\n    assert receipt.upstream_schema_version == "OLA-017"\n    assert receipt.upstream_engine_id == "OLA-017"\n    assert receipt.acquisition_batch_id == bundle.acquisition_batch_id\n    assert receipt.canonical_count == 5\n    assert receipt.persistence_count == 5\n    assert receipt.transition_count == 0\n    assert receipt.lineage_market_count_after == 5\n    assert receipt.lineage_record_count_after == 5\n\n    return bridge, receipt\n\n\ndef run_repeated_bundle_test():\n    bridge, _ = run_first_bundle_test()\n\n    receipt = bridge.advance(\n        bundle=build_bundle(\n            cycle_number=2,\n            completed_at=T2,\n        )\n    )\n\n    assert receipt.transition_count == 0\n    assert receipt.lineage_market_count_after == 5\n    assert receipt.lineage_record_count_after == 10\n\n    ledger = (\n        bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    for head in ledger.heads().values():\n        assert head.consecutive_frame_count == 2\n        assert head.dwell_seconds == "15.000000"\n\n    return bridge, receipt\n\n\ndef run_change_bundle_test():\n    bridge, _ = run_repeated_bundle_test()\n\n    receipt = bridge.advance(\n        bundle=build_bundle(\n            cycle_number=3,\n            completed_at=T3,\n            changed_market="KXTEST-BRIDGE-3",\n        )\n    )\n\n    assert receipt.transition_count == 1\n    assert receipt.lineage_record_count_after == 15\n\n    ledger = (\n        bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    changed_head = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-BRIDGE-3",\n    )\n\n    assert changed_head is not None\n    assert changed_head.transition_detected is True\n    assert changed_head.state_changed_at == T3\n    assert changed_head.consecutive_frame_count == 1\n\n    return receipt\n\n\ndef run_wrong_bundle_type_test():\n    bridge = OraclePersistedCohortLineageBridge()\n\n    try:\n        bridge.advance(bundle={"not": "ola-038"})\n        raise AssertionError(\n            "wrong bundle type must fail closed"\n        )\n    except PersistedCohortLineageBridgeContractError:\n        pass\n\n    ledger = (\n        bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    assert ledger.record_count == 0\n\n\ndef run_duplicate_bundle_replay_fail_closed_test():\n    bridge = OraclePersistedCohortLineageBridge()\n    bundle = build_bundle(\n        cycle_number=1,\n        completed_at=T1,\n    )\n\n    bridge.advance(bundle=bundle)\n\n    try:\n        bridge.advance(bundle=bundle)\n        raise AssertionError(\n            "duplicate persisted bundle replay must fail closed"\n        )\n    except PersistedCohortLineageBridgeContractError:\n        pass\n\n    ledger = (\n        bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    assert ledger.record_count == 5\n\n\ndef run_deterministic_bridge_replay_test():\n    first = OraclePersistedCohortLineageBridge()\n    second = OraclePersistedCohortLineageBridge()\n\n    bundles = (\n        build_bundle(\n            cycle_number=1,\n            completed_at=T1,\n        ),\n        build_bundle(\n            cycle_number=2,\n            completed_at=T2,\n        ),\n        build_bundle(\n            cycle_number=3,\n            completed_at=T3,\n            changed_market="KXTEST-BRIDGE-5",\n        ),\n    )\n\n    first_receipts = []\n    second_receipts = []\n\n    for bundle in bundles:\n        first_receipts.append(first.advance(bundle=bundle))\n        second_receipts.append(second.advance(bundle=bundle))\n\n    assert first_receipts == second_receipts\n\n    first_records = (\n        first\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .records()\n    )\n    second_records = (\n        second\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n        .records()\n    )\n\n    assert first_records == second_records\n\n    return first_receipts\n\n\ndef main():\n    _, first = run_first_bundle_test()\n    _, second = run_repeated_bundle_test()\n    third = run_change_bundle_test()\n\n    run_wrong_bundle_type_test()\n    run_duplicate_bundle_replay_fail_closed_test()\n\n    replayed = run_deterministic_bridge_replay_test()\n\n    result = {\n        "schema_version": third.schema_version,\n        "engine_id": third.engine_id,\n        "status": "passed",\n        "ola_038_bundle_consumed": True,\n        "ola_037_coordinator_consumed": True,\n        "bundle_hash_preserved": True,\n        "ola_017_identity_preserved_end_to_end": True,\n        "acquisition_batch_identity_preserved": True,\n        "canonical_count_preserved": True,\n        "persistence_count_preserved": True,\n        "cycle_completed_at_preserved": True,\n        "exact_canonical_observation_objects_forwarded": True,\n        "first_persisted_bundle_advanced_lineage": (\n            first.lineage_record_count_after == 5\n        ),\n        "repeated_bundle_advanced_dwell": (\n            second.lineage_record_count_after == 10\n        ),\n        "changed_bundle_detected_transition": (\n            third.transition_count == 1\n        ),\n        "wrong_bundle_type_fails_closed": True,\n        "duplicate_bundle_replay_fails_closed": True,\n        "deterministic_bridge_replay_valid": (\n            len(replayed) == 3\n        ),\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": third.read_only,\n        "execution_allowed": third.execution_allowed,\n        "execution_adapter_resolved": (\n            third.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            third.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            third.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            third.order_placement_allowed\n        ),\n        "funds_moved": third.funds_moved,\n        "portfolio_mutated": third.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-039 Oracle Persisted Cohort "\n        "Lineage Bridge"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-039 INSTALLER")
    print(" ORACLE PERSISTED COHORT LINEAGE BRIDGE")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-039 Oracle Persisted Cohort "
        "Lineage Bridge installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_039_oracle_persisted_"
        "cohort_lineage_bridge.py"
    )


if __name__ == "__main__":
    main()
